function kClosest(points: [number, number][], k: number): [number, number][] {
  if (k <= 0) return []
  const dist = ([x, y]: [number, number]) => x * x + y * y
  // Max-heap by distance: the farthest kept point sits at heap[0]
  const heap: [number, number][] = []
  const swap = (i: number, j: number) => {
    ;[heap[i], heap[j]] = [heap[j]!, heap[i]!]
  }
  const siftUp = (i: number) => {
    while (i > 0) {
      const p = Math.floor((i - 1) / 2)
      if (dist(heap[i]!) <= dist(heap[p]!)) return
      swap(i, p)
      i = p
    }
  }
  const siftDown = (i: number) => {
    for (;;) {
      let c = 2 * i + 1
      if (c >= heap.length) return
      if (c + 1 < heap.length && dist(heap[c + 1]!) > dist(heap[c]!)) c++
      if (dist(heap[i]!) >= dist(heap[c]!)) return
      swap(i, c)
      i = c
    }
  }
  for (const p of points) {
    heap.push(p)
    siftUp(heap.length - 1)
    if (heap.length > k) {
      heap[0] = heap.pop()! // replace the farthest with the last item
      siftDown(0)
    }
  }
  return heap
}

