def k_closest(points, k):
    heap = []  # max-heap by distance, via negation
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)  # remove the farthest
    return [[x, y] for _, x, y in heap]
